function log(msg,color=''){logs.push({msg,color,time:new Date().toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'})});logs=logs.slice(-12);$('#logEntries').innerHTML=logs.slice(-3).map(l=>`<div class="${color}"><time>${l.time}</time>${escapeHTML(l.msg)}</div>`).join('');}
let announceTimeout;
function announce(t,s=''){$('#announcement').innerHTML=escapeHTML(t)+(s?`<small>${escapeHTML(s)}</small>`:'');$('#announcement').hidden=false;clearTimeout(announceTimeout);announceTimeout=setTimeout(()=>$('#announcement').hidden=true,3000);}
function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y);}
