function refreshStats(){st=R.stats(state,buffs);hero.hp=Math.min(hero.hp,st.maxHp);hero.mp=Math.min(hero.mp,st.mp);}
function gainXP(n){const a=R.awardXP(state,n*(1+st.expP/100)*(state.xpBoostSeconds>0?2:1));if(a){refreshStats();hero.hp=st.maxHp;hero.mp=st.mp;effects.push({kind:'level',x:hero.x,y:hero.y,life:2,max:2});announce('Đột phá · Cấp '+state.level,`+${a*5} tiềm năng · +${a} điểm kỹ năng`);log('Đã lên cấp '+state.level,'gold');tone('coin');}updateUI();}
