function addParticles(x,y,color,n=10){if(!state.settings.particles)return;for(let i=0;i<Math.min(n,30);i++){const a=Math.random()*6.28,s=25+Math.random()*100;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-20,life:.25+Math.random()*.5,color,size:1+Math.random()*3});}}
