function spawnEnemies(){enemies=[];target=null;const z=ZONES[state.zone],rng=seeded(849+state.zone*77);if(z.safe_town&&!instance)return;let roster=z.nominal_creature_spawns.length?z.nominal_creature_spawns:ZONES[1].nominal_creature_spawns;
 if(instance){if(instance.type==='arena'){let e=makeEnemy(roster[0].creature_id,W*.65,H*.5,0,true);e.name='Đối thủ đấu trường';e.level=state.level;e.maxHp=e.hp=st.maxHp*4;e.attack=st.attack*.6;e.defP=e.defM=st.defense;e.exp=0;e.gold=0;enemies=[e];return;}if(instance.wave===4){const boss=z.boss_id||ZONES[1].boss_id;enemies=[makeEnemy(boss,W*.65,H*.5,0,true)];return;}}
 let index=0;for(const row of roster){const count=instance?Math.min(6,2+instance.wave):row.count;for(let i=0;i<count;i++){let x=100+rng()*(W-200),y=200+rng()*(H-300);if(dist({x,y},hero)<160)x=Math.min(W-80,x+220);const e=makeEnemy(row.creature_id,x,y,index++);if(e)enemies.push(e);}}
 if(!instance&&z.boss_always_flag&&z.boss_id)enemies.push(makeEnemy(z.boss_id,W*.75,H*.5,index,true));}
function travel(index,force=false){if(!ZONES[index])return;const z=ZONES[index];if(!force&&!state.demo&&!z.safe_town&&state.level<z.level){toast('Bản đồ yêu cầu cấp '+z.level,true);return;}modal=null;$('#modalRoot').innerHTML='';state.zone=index;W=z.width_tiles*32;H=z.height_tiles*32;hero.x=W*.48;hero.y=H*.61;hero.hp=st.maxHp;hero.mp=st.mp;hero.invuln=3;hero.shield=0;hero.hot=null;dead=false;camera={x:hero.x,y:hero.y};auto=false;updateAuto();target=moveTarget=null;effects=[];projectiles=[];loots=[];pendingHits=[];minions=[];buffs=[];refreshStats();hero.hp=st.maxHp;hero.mp=st.mp;instance=null;bossCooldown=0;makeTerrain();spawnEnemies();buildNPCs();save();updateUI();announce(z.name,z.safe_town?'Thành trấn · Gặp NPC để nhận dịch vụ':z.label);}
