 if(modal==='settings'){html=shell('Cài đặt','KIẾM VỰC · BẢN MỞ RỘNG',`${[['sound','Âm thanh chiến đấu'],['particles','Hiệu ứng hạt'],['autoStats','Tự phân tiềm năng khi tăng cấp']].map(([k,t])=>`<div class="settings-row"><h3>${t}</h3><button class="toggle" data-toggle="${k}" aria-label="${t}" aria-pressed="${state.settings[k]}"></button></div>`).join('')}${state.demo?`<div class="settings-row"><h3>Bất tử khi thử chiêu</h3><button class="toggle" data-demo-toggle="invincible" aria-pressed="${demoOptions.invincible}" aria-label="Bất tử khi thử chiêu"></button></div><div class="settings-row"><h3>Bỏ hồi chiêu trong chế độ thử</h3><button class="toggle" data-demo-toggle="noCooldown" aria-pressed="${demoOptions.noCooldown}" aria-label="Bỏ hồi chiêu trong chế độ thử"></button></div>`:''}<div class="button-row" style="margin-top:20px">${btn('Lưu ngay','id="manualSave"')}${btn('Xuất bản lưu','id="exportSave"')}${btn('Tạo hành trình mới · giữ bản sao','id="newJourney"')}${btn('Khôi phục hành trình trước','id="restoreJourney"')}${btn('Nhập bản lưu','id="importSave"')}${btn(state.daily===dayKey()?'Đã nhận quà hôm nay':'Nhận quà hôm nay','id="dailyReward" '+(state.daily===dayKey()?'disabled':''))}</div><div class="button-row" style="margin-top:12px">${state.demo?btn('Về hành trình đang lưu','id="leaveDemo"',true):btn('Thử toàn bộ ở Lv400','id="startDemo"')}${btn('Hướng dẫn','data-open="help"')}</div><p class="muted">Tự lưu mỗi 5 giây trên trình duyệt hiện tại. Chế độ thử không ghi đè hành trình. Mã và đồ họa được tự viết; bản này chưa có máy chủ online.</p>`,'settings');}
 if(modal==='help'){html=shell('Cẩm nang','14 PHÁI · 112 CHIÊU · CẤP 1–400',`<div class="help-grid"><div><strong>Di chuyển & đánh</strong><p>WASD hoặc chạm đất. Chạm quái để tiếp cận và đánh. Space đánh thường. T bật tự đánh; trong thành sẽ dẫn tới mục tiêu nhiệm vụ.</p></div><div><strong>8 kỹ năng mỗi phái</strong><p>Phím 1–8. Học đúng cấp ở Võ Sư, nâng tối đa 10. Tuyệt kỹ mở Lv120. Q dùng thuốc máu, E dùng thuốc nội lực.</p></div><div><strong>86 nhiệm vụ</strong><p>J mở hành trình. Dẫn đường tìm đúng quái, vật phẩm, NPC. Lò rèn và tổ đội NPC xử lý nhiệm vụ rèn và chiêu mộ.</p></div><div><strong>Trang bị & thú</strong><p>B mở túi. 10 vị trí trang bị, cường hóa +15, 5 hệ ngọc. Mua trứng/thú ở Tạp Hóa rồi dùng trong túi.</p></div><div><strong>Thử mọi tính năng</strong><p>Vào Cài đặt → Thử toàn bộ Lv400 để đổi 14 phái, dùng đủ 8 chiêu và đi 48 map. Không ghi đè bản lưu hành trình.</p></div><div><strong>Hình ảnh & kết nối</strong><p>Nhân vật, quái, NPC, bản đồ và hiệu ứng vẽ trực tiếp bằng Canvas. Bản này chơi đơn, tổ đội và đấu trường dùng NPC.</p></div></div>`,'help');}
 if(modal==='dead'){html=shell('Tĩnh dưỡng','BẠI MỘT TRẬN, VẪN CÒN GIANG HỒ',`<div class="dead-content">${icon('feather')}<h3>Một lần vấp ngã.</h3><p>Hồi sinh để tiếp tục. EXP hiện tại giảm theo cấp khi tử trận; trang bị được giữ. Tự đánh sẽ tự hồi sinh sau 5 giây.</p>${btn('Hồi sinh','id="reviveBtn"',true)}</div>`,'user');}
