function advanceSimulation(elapsed){let remaining=Math.min(2,Math.max(0,elapsed));while(remaining>.000001){const dt=Math.min(.05,remaining);step(dt);remaining-=dt;}}
function updateProjectiles(dt){for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i],start={x:p.x,y:p.y};if(p.homing?.alive){const a=Math.atan2(p.homing.y-p.y,p.homing.x-p.x);p.vx=Math.cos(a)*p.speed;p.vy=Math.sin(a)*p.speed;}p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;
 if(p.fall){if(p.life<=.0001){effect('ring',p.fall.x,p.fall.y,{r:p.explosion,life:.3,color:p.color});for(const e of enemies)if(e.alive&&dist(e,p.fall)<p.explosion+(e.boss?40:15))damageEnemy(e,p.mult,p.params);projectiles.splice(i,1);}continue;}
 const hits=enemies.filter(e=>e.alive&&!p.hit.has(e)&&R.segmentDistance(e,start,p)<(p.radius||9)+(e.boss?40:15)).sort((a,b)=>dist(a,start)-dist(b,start));let ended=false;
 for(const e of hits){p.hit.add(e);if(p.explosion){effect('ring',e.x,e.y,{r:p.explosion,life:.35,color:p.color});for(const other of enemies)if(other.alive&&dist(other,e)<p.explosion+(other.boss?40:15))damageEnemy(other,p.mult,p.params);}else damageEnemy(e,p.mult,p.params);if(!p.piercing){ended=true;break;}}
 if(ended||p.life<=0)projectiles.splice(i,1);
}}
