function drawHero(c,x,y,scale=1,still=false,profile=CLASSES[state.classId]){c.save();c.translate(x,y);c.scale(scale,scale);let w=still?0:Math.sin(hero.walk)*(hero.moving?1:0),dir=still?1:hero.dir;ellipse(c,0,3,19,7,'#061c1c55');c.scale(dir,1);let bob=still?0:Math.sin(gameTime*2)*.7;
  const col=profile.color;poly(c,[[-7,-30],[-18,-9],[-5,-3],[9,-10],[8,-31]],'#264541');poly(c,[[-9,-26],[-20,-11],[-10,-9],[-3,-24]],'#78917c');poly(c,[[-7,-14],[-10,-3-w*4],[-2,1-w*4],[2,-16]],'#253b3b');poly(c,[[2,-15],[2,0+w*4],[10,1+w*4],[9,-15]],'#344b45');line(c,-10,1-w*4,-2,2-w*4,'#b9ac7f',3);line(c,3,2+w*4,11,2+w*4,'#b9ac7f',3);
  c.translate(0,bob);poly(c,[[-9,-34],[6,-35],[12,-17],[5,-9],[-11,-12]],col);poly(c,[[1,-34],[9,-30],[11,-14],[3,-13]],'#436b5b');line(c,-10,-15,11,-16,'#d7b979',3);line(c,0,-32,-2,-17,'#dce3bd',2);poly(c,[[-10,-31],[-17,-20],[-11,-16],[-5,-29]],'#5b8271');ellipse(c,-14,-18,3,3,'#dab28a');poly(c,[[7,-31],[13,-23],[18,-24],[17,-29],[12,-36]],col);ellipse(c,17,-25,3,3,'#ddbb92');
  ellipse(c,0,-44,10,11,'#d2b38a');poly(c,[[-11,-45],[-9,-54],[2,-58],[11,-51],[9,-41],[4,-44],[-5,-43]],'#233c38');poly(c,[[-12,-48],[0,-58],[13,-49],[6,-47],[-4,-47]],'#304c40');line(c,-11,-49,11,-49,'#ccae70',2);poly(c,[[5,-58],[7,-66],[10,-58]],'#c4b47e');line(c,-3,-40,1,-40,'#263b33',1.6);line(c,5,-40,7,-40,'#263b33',1.6);line(c,-1,-35,4,-35,'#9e7955',1);
  drawWeapon(c,profile,still);c.restore();}
function drawWolf(c,e){c.save();c.translate(e.x,e.y);ellipse(c,0,4,24,8,'#071c1d45');c.scale(e.dir,1);let w=Math.sin(e.walk)*5;let palette=ZONES[state.zone].biome===2?['#c5d4c7','#e2e7d3','#8fa9a4']:ZONES[state.zone].biome>=3?['#7c7f96','#9b9caf','#5b6079']:['#8a9a85','#b1b79b','#667a6e'];if(e.hit>0)palette=['#d8d6ad','#ede3b7','#a4b395'];for(let i of [-1,1]){line(c,i*13,-12,i*16+w*i,2,palette[2],5);}poly(c,[[-22,-14],[-17,-26],[-7,-29],[11,-26],[25,-19],[21,-8],[-10,-7]],palette[0]);poly(c,[[-18,-25],[-8,-32],[6,-27],[13,-29],[16,-21],[-8,-19]],palette[1]);poly(c,[[11,-29],[11,-41],[18,-34],[22,-40],[25,-25],[36,-18],[33,-12],[16,-13]],palette[0]);poly(c,[[14,-36],[15,-29],[19,-31]],'#5b6a61');poly(c,[[23,-24],[35,-18],[31,-15],[23,-17]],palette[1]);ellipse(c,26,-25,2,1.5,ZONES[state.zone].biome>=3?'#d4a4d9':'#e9d59a');ellipse(c,35,-17,2,2,'#2b4b43');poly(c,[[-20,-19],[-36,-34],[-31,-17],[-20,-9]],palette[2]);c.restore();}
function drawBoss(c,e){c.save();c.translate(e.x,e.y);ellipse(c,0,8,47,15,'#06231e66');const walk=Math.sin(e.walk)*4,flash=e.hit>0;
  for(let i of [-1,1])poly(c,[[i*6,-29],[i*25,-26],[i*27+walk*i,7],[i*8+walk*i,8]],'#3c4940');poly(c,[[-28,-62],[23,-65],[34,-19],[18,-9],[-28,-16],[-35,-40]],flash?'#afb58e':'#566c56');poly(c,[[-20,-57],[17,-59],[22,-25],[-15,-24]],'#788061');poly(c,[[-15,-56],[18,-56],[12,-42],[-11,-42]],'#d0ad6a');poly(c,[[-33,-58],[-48,-49],[-36,-33],[-22,-42]],'#898967');poly(c,[[26,-59],[44,-46],[34,-26],[18,-42]],'#808364');line(c,-37,-37,-43,-13,'#5b6b50',12);line(c,35,-34,49,-44,'#5b6b50',11);line(c,50,-15,46,-89,'#8e7951',6);poly(c,[[46,-88],[72,-88],[78,-67],[53,-59],[47,-69]],'#9ea68b');line(c,75,-86,80,-68,'#e0c48a',3);
  poly(c,[[-19,-69],[-16,-90],[1,-99],[19,-88],[17,-65],[1,-60]],flash?'#ece5b3':'#929875');poly(c,[[-15,-87],[-28,-109],[-11,-99],[-6,-88]],'#c3b284');poly(c,[[11,-88],[26,-110],[23,-90],[17,-80]],'#c3b284');poly(c,[[-14,-79],[-4,-76],[-7,-72],[-14,-73]],'#eac57d');poly(c,[[3,-77],[13,-81],[13,-75],[5,-72]],'#eac57d');poly(c,[[-7,-65],[2,-70],[9,-64],[0,-60]],'#374b40');line(c,-24,-18,27,-18,'#bca071',5);ellipse(c,1,-19,6,7,'#cbb070');c.restore();}
function drawLoot(c,l){const t=gameTime-l.time,colors=['#b8c4a3','#84bc91','#7fb4d3','#c2a6e4','#e7c57f','#e0a6cb'],color=l.kind==='gold'?'#d5bb75':colors[l.item.rarity];c.save();c.translate(l.x,l.y);if(l.kind==='item'){let grad=c.createLinearGradient(0,-65,0,0);grad.addColorStop(0,color+'00');grad.addColorStop(1,color+'55');c.fillStyle=grad;c.fillRect(-4,-65,8,65);ellipse(c,0,0,14,5,color+'33');poly(c,[[0,-16+Math.sin(t*3)*2],[6,-9],[0,-2],[-6,-9]],color);c.fillStyle=color;c.font='8px system-ui';c.textAlign='center';c.fillText(itemName(l.item),0,14);}else{ellipse(c,0,0,10,4,'#c5ae7144');ellipse(c,0,-5,6,4,'#d8bf78');ellipse(c,0,-7,6,3,'#eed295');line(c,-1,-8,-1,-5,'#a38c4b',1);}c.restore();}
function drawEffect(c,e){const t=1-e.life/e.max;c.save();c.translate(e.kind==='shield'?hero.x:e.x,e.kind==='shield'?hero.y:e.y);c.globalAlpha=Math.min(1,e.life*4);if(e.kind==='click'){c.strokeStyle='#c1d7a6';c.lineWidth=1.3;c.beginPath();c.ellipse(0,0,12+t*16,5+t*7,0,0,Math.PI*2);c.stroke();}
  if(e.kind==='slash'||e.kind==='wave'){c.rotate(e.angle);c.strokeStyle=e.color;c.shadowColor=e.color;c.shadowBlur=10;c.lineWidth=e.kind==='slash'?5:9;c.beginPath();c.ellipse(t*80,0,e.r*(.3+t*.6),e.r*.5,-Math.PI/6,-1.3,1.3);c.stroke();c.lineWidth=1;c.strokeStyle='#eef4d7';c.stroke();}
  if(e.kind==='ring'||e.kind==='level'){const r=(e.r||100)*Math.min(1,t*2);c.strokeStyle=e.color||'#e3ce8c';c.shadowColor=c.strokeStyle;c.shadowBlur=13;c.lineWidth=3-t*2;c.beginPath();c.ellipse(0,0,r,r*.6,0,0,Math.PI*2);c.stroke();c.globalAlpha*=.2;c.fillStyle=c.strokeStyle;c.fill();if(e.kind==='level'){c.globalAlpha=e.life/e.max*.4;c.fillStyle='#e8d8a1';c.fillRect(-19,-180,38,180);}}
  if(e.kind==='danger'){c.fillStyle='#cf694b33';c.strokeStyle='#e9a070';c.lineWidth=2;c.beginPath();c.ellipse(0,0,e.r,e.r*.67,0,0,Math.PI*2);c.fill();c.stroke();c.beginPath();c.ellipse(0,0,e.r*t,e.r*t*.67,0,0,Math.PI*2);c.stroke();}
  if(e.kind==='beam'){c.strokeStyle=e.color;c.lineWidth=3;c.shadowColor=e.color;c.shadowBlur=14;c.beginPath();c.moveTo(0,0);for(let j=1;j<=7;j++)c.lineTo((e.tx-e.x)*j/7+(j<7?Math.sin(j*8)*9:0),(e.ty-e.y)*j/7);c.stroke();}if(e.kind==='heal'||e.kind==='shield'){c.strokeStyle=e.kind==='heal'?'#9de0b5':e.color;c.lineWidth=2;c.shadowColor=c.strokeStyle;c.shadowBlur=12;c.beginPath();c.ellipse(0,-23,e.kind==='shield'?31:20+t*60,e.kind==='shield'?43:12+t*25,0,0,Math.PI*2);c.stroke();}if(e.kind==='projectile'){let x=(e.tx-e.x)*t,y=(e.ty-e.y)*t;line(c,x,y,x-(e.tx-e.x)*.15,y-(e.ty-e.y)*.15,e.color,3);ellipse(c,x,y,4,3,'#e8eed2');}
  if(e.kind==='dash'){line(c,0,-20,e.tx-e.x,e.ty-e.y-20,'#b5dbe377',15);line(c,0,-20,e.tx-e.x,e.ty-e.y-20,'#e4eee977',3);}
  if(e.kind==='rain'){let rng=seeded(42);for(let j=0;j<15;j++){let x=(rng()-.5)*e.r*1.6,y=(rng()-.5)*e.r*.8,fall=((t*3+j/15)%1);c.globalAlpha=Math.sin(fall*Math.PI)*.9;c.shadowColor='#e9cb83';c.shadowBlur=10;line(c,x+15,y-180+fall*180,x,y-150+fall*180,'#e6d3a0',3);line(c,x+13,y-180+fall*180,x+2,y-150+fall*180,'#f5edc9',1);}c.globalAlpha=.3*e.life;c.strokeStyle='#d7c17e';c.lineWidth=1;c.beginPath();c.ellipse(0,0,e.r,e.r*.55,0,0,Math.PI*2);c.stroke();}c.restore();}
function makeTerrain(){ground.width=W;ground.height=H;decor=[];const c=groundCtx,z=ZONES[state.zone],rng=seeded(2849+state.zone*9973);c.fillStyle=z.base;c.fillRect(0,0,W,H);for(let i=0;i<16000;i++){c.globalAlpha=.1+rng()*.35;c.fillStyle=z.grass[Math.floor(rng()*4)];c.fillRect(rng()*W,rng()*H,1+rng()*4,1+rng()*2);}c.globalAlpha=1;
 const wet=z.biome!==1,xRiver=W*(.12+(state.zone%3)*.025);if(wet){c.fillStyle=z.water;c.beginPath();c.moveTo(0,H*.1);c.bezierCurveTo(xRiver*1.8,H*.12,xRiver*.4,H*.4,xRiver*1.7,H*.65);c.bezierCurveTo(xRiver*2,H*.85,xRiver*.8,H*.95,0,H);c.closePath();c.fill();c.strokeStyle=z.grass[2];c.lineWidth=12;c.stroke();decor.push({kind:'bridge',x:xRiver*1.1,y:H*.57,scale:1});}
 const center={x:W*.5,y:H*.58};c.strokeStyle=z.biome===2?'#b4c1ac':z.biome===1?'#aa976f':'#7f8d6f';c.lineWidth=70;c.lineCap='round';c.lineJoin='round';c.beginPath();c.moveTo(W*.48,H);c.quadraticCurveTo(W*.4,H*.7,center.x,center.y);c.quadraticCurveTo(W*.65,H*.3,W*.7,80);c.stroke();c.beginPath();c.moveTo(30,H*.57);c.quadraticCurveTo(W*.3,H*.42,center.x,center.y);c.lineTo(W-30,H*.6);c.stroke();
 ellipse(c,center.x,center.y,z.safe_town?310:135,z.safe_town?205:75,z.biome===2?'#aebcad':'#829076');for(let j=-5;j<6;j++)for(let i=-10;i<11;i++){const x=center.x+i*27+j*9,y=center.y+j*18;if(Math.hypot((x-center.x)/1.5,y-center.y)<(z.safe_town?190:65))poly(c,[[x,y],[x+24,y-2],[x+26,y+13],[x+2,y+15]],['#8d997e','#879576','#9a9f82'][(i+j+30)%3],'#667b6533');}
 if(z.safe_town){decor.push({kind:'house',x:W*.5,y:H*.28,scale:1.1},{kind:'house',x:W*.76,y:H*.43,scale:.85},{kind:'house',x:W*.25,y:H*.37,scale:.8});decor.push({kind:'gate',x:W*.48,y:H*.88,scale:1.1});}else if(state.zone%3!==0)decor.push({kind:'gate',x:W*.7,y:170,scale:.8});
 const clear=(x,y)=>Math.hypot((x-center.x)/1.4,y-center.y)<(z.safe_town?260:100)||z.safe_town&&y<H*.45&&Math.abs(x-W*.5)<175||Math.abs(x-W*.48)<60;
 for(let i=0;i<(z.biome===1?24:80);i++){const x=60+rng()*(W-120),y=150+rng()*(H-200);if(clear(x,y)||wet&&x<xRiver*1.6)continue;decor.push({kind:rng()<.15?'cherry':/bamboo|truc/.test(z.theme_id)&&rng()<.5?'bamboo':'tree',x,y,scale:.7+rng()*.6,seed:i+state.zone*80});}
 for(let i=0;i<45;i++){const x=55+rng()*(W-110),y=120+rng()*(H-180);if(clear(x,y))continue;decor.push({kind:'rock',x,y,scale:.35+rng()*.7});}
 for(let i=0;i<6;i++){const a=i/6*6.28;decor.push({kind:'lantern',x:center.x+Math.cos(a)*(z.safe_town?320:160),y:center.y+Math.sin(a)*(z.safe_town?220:105),scale:.9});}
 const glow=c.createRadialGradient(center.x,center.y,50,center.x,center.y,600);glow.addColorStop(0,'#d9d39914');glow.addColorStop(1,'#071c1a00');c.fillStyle=glow;c.fillRect(0,0,W,H);
}
function drawWeapon(c,profile,still){const id=profile.class_id,col=profile.color;c.save();c.translate(17,-25);if(!profile.ranged_basic_attack)c.rotate(hero.attackTime>0&&!still?-.95+hero.attackTime*4.5:.32);
 const blade=()=>{poly(c,[[-1,7],[-2,-25],[1,-42],[4,-25],[3,7]],'#d0e1d1');line(c,-5,0,8,0,'#d3b77d',3);line(c,1,3,1,11,'#7e6746',3);};
 if(id==='kiem')blade();
 else if(id==='dao'){line(c,1,11,1,-30,'#a58a60',4);poly(c,[[1,-33],[20,-39],[24,-15],[8,-7],[1,-12]],'#bdcbb8');line(c,23,-35,25,-17,'#ead5a4',2);}
 else if(id==='cung'||id==='camy'||id==='coquan'){c.strokeStyle=id==='cung'?'#d8ba7c':col;c.lineWidth=3;c.beginPath();c.ellipse(5,-8,id==='cung'?10:17,id==='cung'?23:13,0,-1.5,1.5);c.stroke();line(c,5,-30,5,13,'#d8dfc2',1);if(id!=='cung')line(c,-7,-8,25,-8,'#a99c76',5);line(c,-5,-8,34,-8,'#cfdfcc',1.5);}
 else if(id==='phap'||id==='loi'){line(c,1,10,3,-37,'#ad956a',3);if(id==='phap'){ellipse(c,3,-42,6,9,col);ellipse(c,3,-43,3,5,'#e6d7f6');}else poly(c,[[5,-55],[-4,-40],[3,-40],[-1,-27],[12,-45],[5,-45]],'#f4e4a6');}
 else if(id==='bua'){for(let j=-2;j<=2;j++){const a=j*.3;poly(c,[[0,7],[Math.sin(a)*25,-25],[Math.sin(a+.3)*25,-22]],j%2?'#8ebfb0':'#d1ddbe');line(c,0,7,Math.sin(a)*25,-25,'#b3a275',1);}}
 else if(id==='thich'){blade();c.translate(-29,0);c.rotate(-.7);c.scale(.8,.8);blade();}
 else if(id==='anha'){for(let j=0;j<3;j++)poly(c,[[-2+j*5,2],[j*5-1,-24],[3+j*5,-5]],'#c5d0e2');line(c,-5,3,16,3,'#9a91ad',4);}
 else if(id==='thuan'){ellipse(c,4,-4,15,24,'#6e8b77');ellipse(c,4,-4,11,18,'#c8ba86');line(c,4,-20,4,12,'#e5d8a4',3);line(c,-4,-4,12,-4,'#e5d8a4',3);}
 else if(id==='thuong'){line(c,0,23,0,-57,'#b8a27c',3);poly(c,[[0,-72],[-7,-54],[0,-60],[7,-54]],'#d4e1d0');poly(c,[[0,-51],[17,-43],[2,-37]],'#ca9176');}
 else if(id==='cam'){ellipse(c,0,-5,12,19,'#b88c7b');ellipse(c,0,-3,8,13,'#dfbea2');line(c,0,-41,0,-12,'#9f806e',6);for(let j=-2;j<=2;j++)line(c,j,-39,j,12,'#e7d1a6',.6);}
 else if(id==='liem'){line(c,0,20,0,-48,'#9d8ab4',3);poly(c,[[0,-49],[17,-49],[28,-40],[32,-23],[20,-34],[9,-37],[0,-36]],'#d1c3e1');}c.restore();}
function creatureKind(e){return e.family==='ninja'?'human':['demon','reaper'].includes(e.family)?'ghost':e.family==='titan'?'golem':e.family||'slime';}
function drawCreature(c,e){const kind=creatureKind(e);if(e.dummy){drawTrainingDummy(c,e);return;}if(e.boss){if(['human','ghost','golem'].includes(kind)){drawBoss(c,e);return;}c.save();c.translate(e.x,e.y);c.scale(1.9,1.9);drawCreature(c,{...e,boss:false,x:0,y:0});c.restore();return;}if(['wolf','boar','qilin'].includes(kind)){drawWolf(c,e);if(kind==='boar'){c.save();c.translate(e.x,e.y);c.scale(e.dir,1);poly(c,[[26,-15],[30,-6],[33,-17]],'#e3d6ad');c.restore();}if(kind==='qilin'){c.save();c.translate(e.x,e.y);poly(c,[[20,-34],[30,-57],[27,-32]],'#ddbc7c');c.restore();}return;}
 c.save();c.translate(e.x,e.y);c.scale(e.dir,1);ellipse(c,0,3,20,7,'#0b242244');const z=ZONES[state.zone],col=e.hit>0?'#e4e2b8':z.biome>=3?'#a398b7':z.biome===2?'#c7d9cc':'#8bb790',bob=Math.sin(e.walk)*2;
 if(kind==='slime'){ellipse(c,0,-11+bob,22,16-bob/2,col);ellipse(c,-7,-18+bob,7,4,'#e4efd355');ellipse(c,6,-12+bob,2,3,'#304c46');ellipse(c,-5,-12+bob,2,3,'#304c46');}
 if(kind==='spider'){for(let j=0;j<4;j++)for(const side of [-1,1]){const x=side*(13+j*3),y=-6+j*3;line(c,side*5,-15,x+side*5,-22+j*4,'#5e6d62',3);line(c,x+side*5,-22+j*4,x+side*10,2+Math.sin(e.walk+j)*3,'#5e6d62',2);}ellipse(c,-3,-13,17,12,col);ellipse(c,12,-12,9,8,'#b7bd9b');ellipse(c,16,-14,2,2,'#e8af83');}
 if(kind==='bird'||kind==='bat'){const flap=Math.sin(e.walk*1.8)*13;poly(c,[[-3,-20],[-30,-36+flap],[-19,-12],[0,-10]],col);poly(c,[[3,-20],[30,-36-flap],[19,-12],[0,-10]],col);ellipse(c,0,-19,9,13,'#a5b4a1');poly(c,[[7,-25],[20,-22],[8,-18]],'#cbb37c');ellipse(c,5,-26,2,2,'#2c4240');}
 if(kind==='golem'){poly(c,[[-16,1],[-22,-27],[-15,-40],[14,-42],[25,-23],[17,2]],col);poly(c,[[-16,-39],[-9,-57],[13,-54],[18,-36]],'#aab9a8');line(c,-22,-27,-29,-9,'#718779',10);line(c,23,-27,31,-12,'#718779',10);line(c,-7,-43,-2,-43,'#eed79b',3);line(c,7,-43,12,-43,'#eed79b',3);}
 if(kind==='ghost'){poly(c,[[-18,0],[-13,-38],[0,-49],[14,-38],[20,0],[9,-4],[0,2],[-8,-5]],col);ellipse(c,0,-36,9,11,'#536577');ellipse(c,-4,-37,2,2,'#e2c2ed');ellipse(c,4,-37,2,2,'#e2c2ed');line(c,-14,-27,-25,-34,col,5);line(c,14,-27,25,-36,col,5);}
 if(['snake','hydra','dragon','scorpion','treant','mushroom','frog'].includes(kind))drawWildShape(c,kind,col,e.walk);
 if(kind==='human'){poly(c,[[-11,-29],[8,-30],[13,-3],[-14,-3]],col);line(c,-7,-3,-10,3+Math.sin(e.walk)*3,'#3d4e46',5);line(c,6,-3,9,3-Math.sin(e.walk)*3,'#3d4e46',5);ellipse(c,0,-39,9,10,'#bbaa8c');poly(c,[[-11,-40],[0,-51],[10,-42]],'#4e625a');line(c,13,-20,22,-43,'#ccd8c0',3);}c.restore();}
function drawNpc(c,n){c.save();c.translate(n.x,n.y);const role=n.role_id,color=['#c4ac7a','#9baebc','#b99eaf','#9eaa84'][n.i%4];ellipse(c,0,3,18,6,'#142e2655');poly(c,[[-10,-28],[9,-29],[13,0],[-13,0]],color);line(c,0,-27,0,0,'#e1d0a1',2);ellipse(c,0,-39,9,10,'#cfb18c');poly(c,[[-16,-41],[0,-55],[17,-41]],n.i%2?'#667a6a':'#b1a175');if(role==='thoren')line(c,17,-13,17,-40,'#b7c6b4',6);else if(role==='vosu')line(c,16,-10,26,-48,'#d5dcc5',3);c.textAlign='center';c.font='9px system-ui';c.shadowColor='#0e2521';c.shadowBlur=4;c.fillStyle='#e5d8b1';c.fillText(n.display_name,0,-65);const q=currentQuest();if(q&&(q.giver_role_id===role||q.mechanical_requirements.npc===role)){c.fillStyle=R.questProgress(state)>=(q.target_count||1)?'#e2c46e':'#95d9b5';c.font='bold 17px system-ui';c.fillText('!',0,-80+Math.sin(gameTime*2)*3);}c.restore();}
